import type { HellaChildren } from "@hellajs/dom";

import { style } from "@hellajs/css";

const base = style({
  alignItems: "stretch",
  display: "flex",
  width: "fit-content",
  "&:has(> [data-slot='button-group'])": {
    gap: "0.5rem",
  },
  "& > *:focus-visible": {
    position: "relative",
    zIndex: "10",
  },
  "&:has(select[aria-hidden='true']:last-child) > [data-slot='select-trigger']:last-of-type": {
    borderBottomRightRadius: "calc(var(--radius) * 0.8)",
    borderTopRightRadius: "calc(var(--radius) * 0.8)",
  },
  "& > [data-slot='select-trigger']:not([class*='w-'])": {
    width: "fit-content",
  },
  "& > input": {
    flex: "1 1 0%",
  },
}, { label: "hella-button-group", layer: "hella" });

const orientation = {
  horizontal: style({
    "& > *:not(:first-child)": {
      borderBottomLeftRadius: "0",
      borderLeftWidth: "0",
      borderTopLeftRadius: "0",
    },
    "& > *:not(:last-child)": {
      borderBottomRightRadius: "0",
      borderTopRightRadius: "0",
    },
  }, { label: "hella-button-group-horizontal", layer: "hella" }),
  vertical: style({
    flexDirection: "column",
    "& > *:not(:first-child)": {
      borderTopLeftRadius: "0",
      borderTopRightRadius: "0",
      borderTopWidth: "0",
    },
    "& > *:not(:last-child)": {
      borderBottomLeftRadius: "0",
      borderBottomRightRadius: "0",
    },
  }, { label: "hella-button-group-vertical", layer: "hella" }),
};

const text = style({
  alignItems: "center",
  backgroundColor: "var(--muted)",
  border: "1px solid var(--border)",
  borderRadius: "calc(var(--radius) * 0.8)",
  display: "flex",
  fontSize: "0.875rem",
  fontWeight: "500",
  gap: "0.5rem",
  paddingInline: "1rem",
  boxShadow: "0 1px 2px 0 rgb(0 0 0 / 0.05)",
  "& svg": {
    pointerEvents: "none",
  },
  "& svg:not([class*='size-'])": {
    height: "1rem",
    width: "1rem",
  },
}, { label: "hella-button-group-text", layer: "hella" });

const separatorBase = style({
  backgroundColor: "var(--border)",
  flexShrink: "0",
  "&[data-orientation='horizontal']": {
    height: "1px",
    width: "100%",
  },
  "&[data-orientation='vertical']": {
    height: "100%",
    width: "1px",
  },
}, { label: "hella-button-group-separator", layer: "hella" });

const separator = style({
  alignSelf: "stretch",
  backgroundColor: "var(--input)",
  margin: "0 !important",
  position: "relative",
  "&[data-orientation='vertical']": {
    height: "auto",
  },
}, { label: "hella-button-group-separator-override", layer: "hella" });

interface ButtonGroupProps {
  children?: HellaChildren;
  orientation?: "horizontal" | "vertical";
  class?: string;
}

export default function ButtonGroup(props: ButtonGroupProps): JSX.Element {
  return (
    <div
      role="group"
      data-slot="button-group"
      data-orientation={props.orientation ?? "horizontal"}
      class={
        [
          base,
          orientation[props.orientation ?? "horizontal"],
          props.class,
        ]
      }
    >
      {props.children}
    </div>
  );
}

interface ButtonGroupTextProps {
  children?: HellaChildren;
  class?: string;
}

export function ButtonGroupText(props: ButtonGroupTextProps): JSX.Element {
  return (
    <div
      data-slot="button-group-text"
      class={
        [text, props.class]
      }
    >
      {props.children}
    </div>
  );
}

interface ButtonGroupSeparatorProps {
  orientation?: "horizontal" | "vertical";
  class?: string;
}

export function ButtonGroupSeparator(props: ButtonGroupSeparatorProps): JSX.Element {
  return (
    <div
      role="separator"
      data-slot="button-group-separator"
      data-orientation={props.orientation ?? "vertical"}
      aria-orientation={props.orientation ?? "vertical"}
      class={
        [
          separatorBase,
          separator,
          props.class,
        ]
      }
    />
  );
}

